import hashlib
import random
import struct

KEYS = ['470FC614', '4A0FC614', '4B9FC614', '4C8FC614', '4D7FC614']

def task_func(hex_keys=KEYS, seed=42):
    try:
        float_values = [
            struct.unpack('!f', bytes.fromhex(hex_key))[0]
            for hex_key in hex_keys
        ]
    except (TypeError, ValueError, struct.error):
        raise ValueError("Invalid hexadecimal string in hex_keys.")

    chosen_float = random.Random(seed).choice(float_values)
    return hashlib.md5(str(chosen_float).encode()).hexdigest()
